// === Tab: mySketch ===
let canvasSize = { w: 0, h: 0 }
let lastTime = 0
let particles = []
let maxSpeed = 6

class Particle {
  constructor (x, y) {
    this.pos = createVector(x, y)
    this.vel = createVector(0, 0)
    this.gravity = createVector(0, 0.002)
    this.acc = createVector(random(-0.2, 0.2), random(-0.2, 0.2))
    this.color = [Math.floor(random(120, 240)), 100, 100, 120]
    this.startTime = millis()
    this.attractor = createVector(0, 0)
  }

  update (x, y) {
    this.prev = this.pos.copy()
    let currTime = millis()
    let timeElapsed = currTime - this.startTime
    if (100 < timeElapsed && timeElapsed < 2000) {
      this.attractor.set(x, y)
      this.attractor.sub(this.pos)
      this.attractor.div(5)
      this.acc.add(this.attractor)
      this.acc.div(500)
    }

    this.acc.add(this.gravity)
    this.vel.add(this.acc)
		this.vel.limit(maxSpeed)
    this.pos.add(this.vel)
  }

  draw () {
    stroke(this.color)
    // fill(this.color)
    const prev = this.prev
    const curr = this.pos
    line(prev.x, prev.y, curr.x, curr.y)
    // ellipse(curr.x, curr.y, 3, 3)
  }

  finished () {
    const { w, h } = canvasSize
    const pos = this.pos
    return pos.x < 0 || pos.x >= w || pos.y < 0 || pos.y >= h
  }
}

function setup () {
  canvasSize.w = windowWidth - 0
  canvasSize.h = windowHeight - 0
  const { w, h } = canvasSize

  lastTime = millis()

  createCanvas(w, h)
  background(0)
}

function draw () {
  colorMode(RGB)
  background(0, 10)

  strokeWeight(2)
  // noStroke()

  colorMode(HSB, 360, 100, 100)

  particles.forEach(p => {
    p.update((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))
    p.draw()
  })

  particles = particles.filter(p => !p.finished())

  var currTime = millis()
  if (currTime - lastTime > int(random(2, 4))) {
    particles.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))))
    lastTime = currTime
  }
}

